"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([[17119],{154:(e,n,o)=>{o.r(n),o.d(n,{assets:()=>l,contentTitle:()=>i,default:()=>d,frontMatter:()=>s,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"id":"2002posts/forumreplies1","title":"","description":"Yesterday I watched the finals of the bel canto competition. Does anyone know what happened to the Inner Mongolian fellow who placed first in the preliminary round? China\'s male tenors are as common as garbage, including the famous ones \u2014 very few are any good, especially dramatic tenors \u2014 there isn\'t a single one. This Inner Mongolian fellow had a rare dramatic tenor voice. Xiaoren and he are both big gorillas, so I truly feel something about this. If anyone knows, please tell Xiaoren \u2014 infinitely grateful.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/2002posts/forumreplies1.md","sourceDirName":"2002posts","slug":"/2002posts/forumreplies1","permalink":"/en/2002posts/forumreplies1","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"forumreplies1","title":"","hide_table_of_contents":true},"sidebar":"y2002postsSidebar","previous":{"title":"4.\u8bba\u521b\u4f5c\u548c\u9605\u8bfb","permalink":"/en/2002posts/poemtheory4"},"next":{"title":"2.\u5c0f\u4eba\u5144\u5e74\u7eaa\u591a\u5927\uff1f","permalink":"/en/2002posts/forumreplies2"}}');var a=o(74848),r=o(28453);const s={id:"forumreplies1",title:"",hide_table_of_contents:!0},i="1. Brother, Stand Tall \u2014 Don't Lie Down",l={},h=[];function c(e){const n={h1:"h1",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"1-brother-stand-tall--dont-lie-down",children:"1. Brother, Stand Tall \u2014 Don't Lie Down"})}),"\n",(0,a.jsx)(n.p,{children:"Yesterday I watched the finals of the bel canto competition. Does anyone know what happened to the Inner Mongolian fellow who placed first in the preliminary round? China's male tenors are as common as garbage, including the famous ones \u2014 very few are any good, especially dramatic tenors \u2014 there isn't a single one. This Inner Mongolian fellow had a rare dramatic tenor voice. Xiaoren and he are both big gorillas, so I truly feel something about this. If anyone knows, please tell Xiaoren \u2014 infinitely grateful."}),"\n",(0,a.jsx)(n.p,{children:"Netizen's reply: Apparently the Inner Mongolian fellow was eliminated after being accused of performing a piece that was not original."}),"\n",(0,a.jsx)(n.p,{children:"(Of course, whether it counts as original may differ between public opinion and the judges' ruling.)"}),"\n",(0,a.jsx)(n.p,{children:'A thousand thanks. He was singing "Gada Merin" at the time, with the melody processed through modulation. Nowadays many pop singers cover songs this way. For such an ambiguous matter to ruin a person \u2014 what a tragedy. If anyone knows this Inner Mongolian fellow, or if he himself can see this post online, please contact Xiaoren. I hope I can help him.'}),"\n",(0,a.jsx)(n.p,{children:'Today I spent time searching online for information about the Inner Mongolian fellow \u2014 came up with nothing. You should know, good dramatic tenors are rarer than giant pandas. In the world today, there are probably fewer than three. The so-called Three Tenors \u2014 in my view, not one of them is up to par. The one who came last year to sing "Cavalleria Rusticana" was passable, but he\'s already over 60. It seems Caruso can only remain an eternal memory.'}),"\n",(0,a.jsx)(n.p,{children:"I say all this just to explain some of the reasons I want to find that Inner Mongolian fellow. After suffering such a blow, if he can't turn the corner, such excellent natural gifts will be destroyed. A good voice should, like Caruso's, be able to produce all the sounds from bass to dramatic tenor. Achieving this depends on both the innate construction of the vocal organs and the training methods used. I feel he already has the exceedingly rare natural gifts and deserves better training and broader learning in all areas. If he needs it, I am very willing to support him in every way. If there are people from CCTV here, or people from Inner Mongolia who know him, I hope you can pass along my intentions."}),"\n",(0,a.jsx)(n.p,{children:"Brother, stand tall \u2014 don't lie down. Sing with the true voice of a real man, like Caruso."})]})}function d(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453:(e,n,o)=>{o.d(n,{R:()=>s,x:()=>i});var t=o(96540);const a={},r=t.createContext(a);function s(e){const n=t.useContext(r);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);